from collections import deque

def get_connected_components(grid, start_pos):
    """Get all connected cells starting from a position (4-connectivity)"""
    start = (start_pos[0], start_pos[1])
    visited = set([start])
    queue = deque([start])

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if (nr, nc) in visited:
                continue
            if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                if grid[nr][nc] == grid[r][c]:
                    visited.add((nr, nc))
                    queue.append((nr, nc))
    return visited

# Analyze connected components for 6, 0, and 7
for color in [0, 6, 7]:
    positions = [p for p in [[13, 16], [13, 17], [13, 18], [13, 19], [13, 20], [13, 21], [13, 22], [14, 16], [15, 16], [16, 16], [17, 16], [18, 16], [19, 16]] if grid[p[0]][p[1]] == color]
    if color == 6:
        positions = [[3, 5], [3, 6], [3, 7], [3, 8], [3, 9], [3, 18], [4, 5], [4, 6], [4, 7], [4, 8], [5, 5], [5, 6], [5, 7], [5, 8], [5, 9], [6, 5], [6, 7], [6, 8], [6, 9], [7, 9], [13, 3], [14, 2], [14, 3], [15, 3], [16, 2], [16, 3]]
    if color == 6:
        # Find all connected components
        components = []
        visited_set = set()
        for pos in positions:
            if pos in visited_set:
                continue
            comp = get_connected_components(grid, pos)
            components.append(comp)

print("Connected components count for color 6:", len(components))
for i, comp in enumerate(components):
